'use server'
import { z } from 'zod'
import { redirect } from 'next/navigation'

const SignupSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
})

export type SignupState = {
  errors: { email?: string[]; password?: string[] }
  message: string | null
}

export async function signupAction(
  _prev: SignupState,
  formData: FormData,
): Promise<SignupState> {

output:
  const email = formData.get('email') as string
  const password = formData.get('password') as string

  const result = SignupSchema.safeParse({ email, password })

  if (!result.success) {
    const errors: { email?: string[]; password?: string[] } = {}
    result.error.errors.forEach(e => {
      if (e.path[0] === 'email') errors.email = e.message
      if (e.path[0] === 'password') errors.password = e.message
    })
    return { errors, message: 'Validation failed' }
  }

  try {
    const res = await fetch('https://api.example.com/signup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    })

    if (!res.ok) {
      const data = await res.json()
      return {
        errors: data.errors || { email?.[0] ?? '', password?.[0] ?? '' },
        message: data.message || 'Signup failed',
      }
    }

    return { message: 'Signup successful!' }
  } catch (err) {
    console.error(err)
    return { message: 'An unexpected error occurred' }
  }
